function whoProves(zoneKey) {
	const flags = /* @__PURE__ */ new Set();
	const zones = /* @__PURE__ */ new Set();
	const addZone = (z) => {
		if (zones.has(z)) return;
		zones.add(z);
		for (const f of POP_ZONE_BY_KEY[z]?.requires ?? []) addFlag(f);
	};
	const addFlag = (f) => {
		if (flags.has(f)) return;
		flags.add(f);
		if (GATE_IMPLIES[f]) {
			for (const g of GATE_IMPLIES[f]) addFlag(g);
			return;
		}
		const z = POP_FLAGS[f]?.zone;
		if (z) addZone(z);
	};
	addZone(zoneKey);
	return [...flags];
}
function flagsFromSightings(rows) {
	const out = /* @__PURE__ */ new Map();
	const sorted = rows.filter((r) => WHO_ZONE[r.zone]).sort((a, b) => a.first_seen.localeCompare(b.first_seen));
	for (const r of sorted) {
		const zone = WHO_ZONE[r.zone];
		for (const flag of whoProves(zone)) if (!out.has(flag)) out.set(flag, {
			flag,
			zone,
			at: r.first_seen
		});
	}
	return out;
}
